import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"组提交","description":"","frontmatter":{"title":"组提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/group-commit.md","filePath":"cs/group-commit.md","lastUpdated":1789023840000}'),m={name:"cs/group-commit.md"};function h(_,a,u,f,B,E){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="组提交" tabindex="-1">组提交 <a class="header-anchor" href="#组提交" aria-label="Permalink to &quot;组提交&quot;">​</a></h1><div class="epigraph"><p>许多事务的 commit 记录挤进同一次日志 fsync：延迟换吞吐，持久性不等式仍是「提交返回 ⇒ 日志已落」。</p><footer>—— 据 Gray and Reuter 组提交；Mohan；磁盘与 NVMe 上的 WAL</footer></div><p><a href="/cs/shadow-paging">上一课</a>对照切根。本课回到 WAL 路径的刷盘：每个提交都 <code>fsync</code> 则磁盘 IOPS 打满，吞吐上不去。组提交（group commit）把一个日志缓冲里的多个 commit 一起刷。持久性等级下一课把「刷到哪」再分级。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提交延迟 ≈ 等刷盘。组：领导者收集一个窗口内的提交者，一次 I/O，大家一起返回。缺口是<strong>窗口</strong>：等太久延迟差；不等则退化成每提交一刷。自适应窗口看队列长度。与并行：组提交是日志尾的串行点，是 OLTP 扩展上限之一——可分区日志缓解，复杂度高。</p><p>steal/no-force 仍成立：数据页不必在组里刷。只刷日志。</p><p><span class="marginnote">Gray and Reuter。MySQL/Postgres 都有组提交实现。本课不调某个 <code>commit_delay</code> 参数表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日志缓冲满或超时或 N 个 commit → flush。返回后事务可见（按隔离：提交可见性还要看锁释放点）。备库半同步后课会等备库 ACK，组提交窗口与复制 ACK 可叠。</p><p>崩溃：组里已刷的全提交，未进这次刷的全部 abort——原子的是这一刷。</p>',10)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22commit%22%5D%20--%3E%20BUF%5B%22%E6%97%A5%E5%BF%97%E5%B0%BE%E7%BC%93%E5%86%B2%22%5D%0A%20%20C2%5B%22commit%22%5D%20--%3E%20BUF%0A%20%20BUF%20--%3E%20FS%5B%22%E4%B8%80%E6%AC%A1%20fsync%22%5D%0A%20%20FS%20--%3E%20OK%5B%22%E6%95%B4%E7%BB%84%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 TDE：加密日志页再刷，CPU 进组路径。与双写：数据页路径独立。校准：优化器不管组提交，但基准 TPC-C 对它极敏感——后课基准。</p><p>无组提交时，用户同步提交延迟=单次 fsync；SSD 仍有上限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义 RPO 的全部等级。也不把组提交当 2PC。异步提交（先返回再刷）属于下一课耐久性放松。</p><p>后课默认：同步提交走组刷日志。持久性等级：同步、异步、备库参与。</p><p>组提交不改变 WAL 不等式，只改变每次 I/O 摊到多少事务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多 commit 共享一次日志 fsync，吞吐升、尾延迟可能升。</li><li>崩溃原子单位是这一刷。</li><li>持久性等级下一课。</li><li>出处：Gray and Reuter；ARIES 实践。</li></ul>',9))])}const T=i(m,[["render",h]]);export{P as __pageData,T as default};
